20251202042628	{"ALTER TABLE exercises ADD COLUMN IF NOT EXISTS how_to TEXT[];"}	add_how_to_column_to_exercises	alexander.preo@gmail.com	\N	\N
20251202043140	{"ALTER TABLE exercises ADD COLUMN IF NOT EXISTS how_to TEXT[];"}	add_how_to_column_to_exercises	alexander.preo@gmail.com	\N	\N
20251204112702	{"alter table public.profiles\n  add column if not exists preferred_training_style text null,\n  add column if not exists include_components jsonb null;\n\nalter table public.exercises\n  add column if not exists movement_pattern text null,\n  add column if not exists tempo_category text null,\n  add column if not exists setup_buffer_sec integer null,\n  add column if not exists is_unilateral boolean null,\n  add column if not exists base_seconds_per_rep numeric null;\n\nalter table public.user_exercises\n  add column if not exists user_seconds_per_rep_override numeric null;"}	adaptive_ai_add_columns	alexander.preo@gmail.com	\N	\N
20251205014910	{"-- Add Personal Record (PR) fields to user_exercises table\nALTER TABLE user_exercises\nADD COLUMN IF NOT EXISTS pr_weight NUMERIC,\nADD COLUMN IF NOT EXISTS pr_reps INTEGER,\nADD COLUMN IF NOT EXISTS pr_performed_at TIMESTAMPTZ;\n\nCOMMENT ON COLUMN user_exercises.pr_weight IS 'Personal record: highest weight successfully completed for this exercise';\nCOMMENT ON COLUMN user_exercises.pr_reps IS 'Reps achieved at PR weight';\nCOMMENT ON COLUMN user_exercises.pr_performed_at IS 'Date when PR was achieved';"}	add_personal_record_fields	alexander.preo@gmail.com	\N	\N
20251205023259	{"-- Backfill movement patterns for existing exercises in the exercises table\n-- Uses heuristic logic to infer patterns from exercise names\n\nUPDATE exercises\nSET movement_pattern = CASE\n  -- Hinge patterns (hip-dominant)\n  WHEN LOWER(name) LIKE '%deadlift%' OR \n       LOWER(name) LIKE '%rdl%' OR \n       LOWER(name) LIKE '%romanian%' OR \n       LOWER(name) LIKE '%hip thrust%' OR \n       LOWER(name) LIKE '%good morning%' OR \n       LOWER(name) LIKE '%hyperextension%' OR \n       LOWER(name) LIKE '%back extension%'\n  THEN 'hinge'\n  \n  -- Squat patterns (knee-dominant)\n  WHEN LOWER(name) LIKE '%squat%' OR \n       LOWER(name) LIKE '%leg press%' OR \n       LOWER(name) LIKE '%hack squat%' OR \n       LOWER(name) LIKE '%goblet squat%' OR \n       LOWER(name) LIKE '%front squat%' OR \n       LOWER(name) LIKE '%back squat%'\n  THEN 'squat'\n  \n  -- Lunge patterns (single-leg)\n  WHEN LOWER(name) LIKE '%lunge%' OR \n       LOWER(name) LIKE '%step up%' OR \n       LOWER(name) LIKE '%step-up%' OR \n       LOWER(name) LIKE '%split squat%' OR \n       LOWER(name) LIKE '%bulgarian%' OR \n       LOWER(name) LIKE '%pistol squat%' OR \n       LOWER(name) LIKE '%single leg%'\n  THEN 'lunge'\n  \n  -- Vertical pull\n  WHEN (LOWER(name) LIKE '%pull up%' OR \n        LOWER(name) LIKE '%pull-up%' OR \n        LOWER(name) LIKE '%pullup%' OR \n        LOWER(name) LIKE '%chin up%' OR \n        LOWER(name) LIKE '%chin-up%' OR \n        LOWER(name) LIKE '%lat pulldown%' OR \n        LOWER(name) LIKE '%lat pull-down%' OR \n        LOWER(name) LIKE '%lat pull down%' OR \n        LOWER(name) LIKE '%pull down%' OR \n        LOWER(name) LIKE '%pulldown%')\n  THEN 'pull_vert'\n  \n  -- Horizontal pull (rows) - exclude upright row\n  WHEN (LOWER(name) LIKE '%row%' OR \n        LOWER(name) LIKE '%face pull%' OR \n        LOWER(name) LIKE '%cable row%' OR \n        LOWER(name) LIKE '%barbell row%' OR \n        LOWER(name) LIKE '%dumbbell row%' OR \n        LOWER(name) LIKE '%t-bar row%')\n       AND LOWER(name) NOT LIKE '%upright row%'\n  THEN 'pull_horiz'\n  \n  -- Vertical push\n  WHEN LOWER(name) LIKE '%overhead press%' OR \n       LOWER(name) LIKE '%ohp%' OR \n       LOWER(name) LIKE '%shoulder press%' OR \n       LOWER(name) LIKE '%military press%' OR \n       LOWER(name) LIKE '%push press%' OR \n       LOWER(name) LIKE '%arnold press%' OR \n       LOWER(name) LIKE '%upright row%' OR \n       LOWER(name) LIKE '%lateral raise%' OR \n       LOWER(name) LIKE '%front raise%'\n  THEN 'push_vert'\n  \n  -- Horizontal push\n  WHEN LOWER(name) LIKE '%bench%' OR \n       LOWER(name) LIKE '%push up%' OR \n       LOWER(name) LIKE '%push-up%' OR \n       LOWER(name) LIKE '%pushup%' OR \n       LOWER(name) LIKE '%dip%' OR \n       LOWER(name) LIKE '%chest press%' OR \n       LOWER(name) LIKE '%pec fly%' OR \n       LOWER(name) LIKE '%pec flye%' OR \n       LOWER(name) LIKE '%chest fly%'\n  THEN 'push_horiz'\n  \n  -- Carry patterns\n  WHEN LOWER(name) LIKE '%carry%' OR \n       LOWER(name) LIKE '%walk%' OR \n       LOWER(name) LIKE '%suitcase%' OR \n       LOWER(name) LIKE '%farmer%'\n  THEN 'carry'\n  \n  -- Default: leave as NULL if pattern cannot be determined\n  ELSE movement_pattern\nEND\nWHERE movement_pattern IS NULL;"}	backfill_movement_patterns	alexander.preo@gmail.com	\N	\N
20251209111034	{"-- Migration: Fix Critical RLS Performance and Add Missing Indexes\n-- Date: 2024-12-19\n-- \n-- This migration addresses:\n-- 1. RLS policy performance (wrap auth.uid() in select)\n-- 2. Missing foreign key indexes\n-- 3. Consolidate duplicate RLS policies\n\n-- ============================================================================\n-- PART 1: Add Missing Foreign Key Indexes\n-- ============================================================================\n\nCREATE INDEX IF NOT EXISTS idx_workout_logs_plan_id \n  ON public.workout_logs(plan_id);\n\nCREATE INDEX IF NOT EXISTS idx_workout_plans_user_id \n  ON public.workout_plans(user_id);\n\nCREATE INDEX IF NOT EXISTS idx_workout_sessions_plan_id \n  ON public.workout_sessions(plan_id);\n\n-- ============================================================================\n-- PART 2: Fix RLS Policies - Wrap auth.uid() in (select auth.uid())\n-- ============================================================================\n\n-- Profiles table policies\nDROP POLICY IF EXISTS \\"Users can view their own profile\\" ON public.profiles;\nDROP POLICY IF EXISTS \\"Users can update their own profile\\" ON public.profiles;\nDROP POLICY IF EXISTS \\"Users manage own profile\\" ON public.profiles;\n\nCREATE POLICY \\"Users manage own profile\\"\nON public.profiles\nFOR ALL\nUSING ((select auth.uid()) = id)\nWITH CHECK ((select auth.uid()) = id);\n\n-- Workout plans table policies\nDROP POLICY IF EXISTS \\"Users can view their own workout plans\\" ON public.workout_plans;\nDROP POLICY IF EXISTS \\"Users can create their own workout plans\\" ON public.workout_plans;\nDROP POLICY IF EXISTS \\"Users can update their own workout plans\\" ON public.workout_plans;\nDROP POLICY IF EXISTS \\"Users can delete their own workout plans\\" ON public.workout_plans;\nDROP POLICY IF EXISTS \\"Users manage own plans\\" ON public.workout_plans;\n\nCREATE POLICY \\"Users manage own workout plans\\"\nON public.workout_plans\nFOR ALL\nUSING ((select auth.uid()) = user_id)\nWITH CHECK ((select auth.uid()) = user_id);\n\n-- Workout logs table policies\nDROP POLICY IF EXISTS \\"Users can view their own workout logs\\" ON public.workout_logs;\nDROP POLICY IF EXISTS \\"Users can create their own workout logs\\" ON public.workout_logs;\nDROP POLICY IF EXISTS \\"Users can update their own workout logs\\" ON public.workout_logs;\nDROP POLICY IF EXISTS \\"Users can delete their own workout logs\\" ON public.workout_logs;\nDROP POLICY IF EXISTS \\"Users manage own logs\\" ON public.workout_logs;\n\nCREATE POLICY \\"Users manage own workout logs\\"\nON public.workout_logs\nFOR ALL\nUSING ((select auth.uid()) = user_id)\nWITH CHECK ((select auth.uid()) = user_id);\n\n-- Workout sessions table policies\nDROP POLICY IF EXISTS \\"Users can view their own workout sessions\\" ON public.workout_sessions;\nDROP POLICY IF EXISTS \\"Users can create their own workout sessions\\" ON public.workout_sessions;\nDROP POLICY IF EXISTS \\"Users can update their own workout sessions\\" ON public.workout_sessions;\nDROP POLICY IF EXISTS \\"Users can delete their own workout sessions\\" ON public.workout_sessions;\n\nCREATE POLICY \\"Users manage own workout sessions\\"\nON public.workout_sessions\nFOR ALL\nUSING ((select auth.uid()) = user_id)\nWITH CHECK ((select auth.uid()) = user_id);\n\n-- User exercises table policies\nDROP POLICY IF EXISTS \\"Users can view own exercises\\" ON public.user_exercises;\nDROP POLICY IF EXISTS \\"Users can view their own exercises\\" ON public.user_exercises;\nDROP POLICY IF EXISTS \\"Users can create own exercises\\" ON public.user_exercises;\nDROP POLICY IF EXISTS \\"Users can create their own exercises\\" ON public.user_exercises;\nDROP POLICY IF EXISTS \\"Users can update own exercises\\" ON public.user_exercises;\nDROP POLICY IF EXISTS \\"Users can update their own exercises\\" ON public.user_exercises;\nDROP POLICY IF EXISTS \\"Users can delete own exercises\\" ON public.user_exercises;\nDROP POLICY IF EXISTS \\"Users can delete their own exercises\\" ON public.user_exercises;\n\nCREATE POLICY \\"Users manage own exercises\\"\nON public.user_exercises\nFOR ALL\nUSING ((select auth.uid()) = user_id)\nWITH CHECK ((select auth.uid()) = user_id);\n\n-- Exercises table policies (public read, service role manage)\nDROP POLICY IF EXISTS \\"Anyone can read exercises\\" ON public.exercises;\nDROP POLICY IF EXISTS \\"Anyone can view master exercises\\" ON public.exercises;\nDROP POLICY IF EXISTS \\"Service role can manage exercises\\" ON public.exercises;\n\n-- Public read access\nCREATE POLICY \\"Public can view exercises\\"\nON public.exercises\nFOR SELECT\nTO public\nUSING (true);\n\n-- Service role can manage (for admin operations)\nCREATE POLICY \\"Service role can manage exercises\\"\nON public.exercises\nFOR ALL\nTO service_role\nUSING (true)\nWITH CHECK (true);\n\n-- ============================================================================\n-- PART 3: Fix Function Search Path (Security)\n-- ============================================================================\n\n-- Fix handle_new_user function\nALTER FUNCTION public.handle_new_user()\nSET search_path = public, pg_temp;\n\n-- Fix migrate_rep_range function (with parameter)\nALTER FUNCTION public.migrate_rep_range(value jsonb)\nSET search_path = public, pg_temp;"}	fix_critical_rls_performance_and_indexes	alexander.preo@gmail.com	\N	\N
20251210083911	{"alter table public.exercises add column if not exists density_score numeric;\nalter table public.exercises add column if not exists implicit_hits jsonb;\n-- optional: clamp expected range for density (informational check)\n-- alter table public.exercises add constraint chk_exercises_density_range check (density_score is null or (density_score >= 0 and density_score <= 10));\n\n-- ensure rls policies remain unaffected (no change)\n"}	add_density_and_implicit_hits_to_exercises	alexander.preo@gmail.com	\N	\N
20251210085513	{"create or replace function public.adjust_bw_exercises(pd jsonb)\nreturns jsonb\nlanguage plpgsql\nas $$\ndeclare\n  out_pd jsonb := pd;\n  new_ws jsonb;\n  new_weeks jsonb := '{}'::jsonb;\n  day_key text;\n  day_val jsonb;\n  wk_key text;\n  wk_val jsonb;\nbegin\n  -- helper to transform a day schedule\n  create temporary table if not exists tmp_dummy(id int);\n  drop table if exists tmp_dummy; -- no-op placeholder to allow nested function? not needed\n  perform 1; -- placeholder\n  \n  -- local function via DO is not available; we'll inline logic via nested blocks\n  -- adjust top-level week_schedule\n  if out_pd ? 'week_schedule' then\n    new_ws := '{}'::jsonb;\n    for day_key, day_val in\n      select key, value from jsonb_each(out_pd->'week_schedule')\n    loop\n      if day_val is null then\n        new_ws := new_ws || jsonb_build_object(day_key, day_val);\n        continue;\n      end if;\n      if day_val ? 'exercises' then\n        new_ws := new_ws || jsonb_build_object(day_key, jsonb_set(day_val, '{exercises}', (\n          select coalesce(jsonb_agg(ex_new), '[]'::jsonb) from (\n            select (\n              case\n                when is_bw and not is_skill then ex\n                  -- apply adjustments\n                  |> (select jsonb_set(ex, '{target_reps}', to_jsonb(greatest(coalesce((ex->>'target_reps')::int,10),10)), true))\n              end\n            )\n          ) as ex_new\n        ), true));\n      else\n        new_ws := new_ws || jsonb_build_object(day_key, day_val);\n      end if;\n    end loop;\n    out_pd := jsonb_set(out_pd, '{week_schedule}', new_ws, true);\n  end if;\n  \n  return out_pd;\nend;\n$$;"}	adjust_bodyweight_volume_in_plan_data	alexander.preo@gmail.com	\N	\N
20251210085539	{"create or replace function public.adjust_bw_exercises(pd jsonb)\nreturns jsonb\nlanguage plpgsql\nas $$\ndeclare\n  out_pd jsonb := coalesce(pd, '{}'::jsonb);\n  new_ws jsonb;\n  new_weeks jsonb := '{}'::jsonb;\n  day_key text;\n  day_val jsonb;\n  wk_key text;\n  wk_val jsonb;\n  ex jsonb;\n  ex_array jsonb;\n  ex_name text;\n  eq text[];\n  diff text;\n  is_bw boolean;\n  is_skill boolean;\n  target_reps int;\n  target_sets int;\n  rest_ex int;\n  new_sets jsonb;\nbegin\n  -- helper to process a day object\n  -- returns transformed day jsonb\n  -- inline block used twice\n  if out_pd ? 'week_schedule' then\n    new_ws := '{}'::jsonb;\n    for day_key, day_val in select key, value from jsonb_each(out_pd->'week_schedule') loop\n      if day_val is null then\n        new_ws := new_ws || jsonb_build_object(day_key, day_val);\n        continue;\n      end if;\n      if day_val ? 'exercises' then\n        ex_array := '[]'::jsonb;\n        for ex in select value from jsonb_array_elements(day_val->'exercises') loop\n          ex_name := ex->>'name';\n          select equipment_needed, difficulty_level\n          into eq, diff\n          from public.exercises\n          where lower(name) = lower(ex_name)\n          limit 1;\n          is_bw := coalesce(eq = '{}', false) or coalesce('Bodyweight' = any(eq), false) or coalesce('Bodyweight/Weighted' = any(eq), false) or eq is null;\n          is_skill := diff in ('Advanced','Elite','Hard');\n          if is_bw and not is_skill then\n            target_reps := greatest(coalesce((ex->>'target_reps')::int,10),10);\n            target_sets := least(coalesce((ex->>'target_sets')::int, coalesce(jsonb_array_length(ex->'sets'),3)),4);\n            rest_ex := least(coalesce((ex->>'rest_time_sec')::int,60),90);\n            if ex ? 'sets' then\n              new_sets := (\n                select coalesce(jsonb_agg(\n                  jsonb_set(\n                    jsonb_set(s, '{reps}', to_jsonb(greatest(coalesce((s->>'reps')::int, target_reps),10)), true),\n                    '{rest_time_sec}', to_jsonb(least(coalesce((s->>'rest_time_sec')::int, rest_ex),90)), true)\n                ), '[]'::jsonb)\n                from jsonb_array_elements(ex->'sets') with ordinality as t(s, ord)\n                where ord <= 4\n              );\n            else\n              new_sets := ex->'sets';\n            end if;\n            ex := jsonb_set(ex, '{target_reps}', to_jsonb(target_reps), true);\n            ex := jsonb_set(ex, '{target_sets}', to_jsonb(target_sets), true);\n            ex := jsonb_set(ex, '{rest_time_sec}', to_jsonb(rest_ex), true);\n            if new_sets is not null then\n              ex := jsonb_set(ex, '{sets}', new_sets, true);\n            end if;\n          end if;\n          ex_array := ex_array || jsonb_build_array(ex);\n        end loop;\n        day_val := jsonb_set(day_val, '{exercises}', ex_array, true);\n      end if;\n      new_ws := new_ws || jsonb_build_object(day_key, day_val);\n    end loop;\n    out_pd := jsonb_set(out_pd, '{week_schedule}', new_ws, true);\n  end if;\n\n  if out_pd ? 'weeks' then\n    new_weeks := '{}'::jsonb;\n    for wk_key, wk_val in select key, value from jsonb_each(out_pd->'weeks') loop\n      if wk_val is null or not (wk_val ? 'week_schedule') then\n        new_weeks := new_weeks || jsonb_build_object(wk_key, wk_val);\n        continue;\n      end if;\n      new_ws := '{}'::jsonb;\n      for day_key, day_val in select key, value from jsonb_each(wk_val->'week_schedule') loop\n        if day_val is null then\n          new_ws := new_ws || jsonb_build_object(day_key, day_val);\n          continue;\n        end if;\n        if day_val ? 'exercises' then\n          ex_array := '[]'::jsonb;\n          for ex in select value from jsonb_array_elements(day_val->'exercises') loop\n            ex_name := ex->>'name';\n            select equipment_needed, difficulty_level\n            into eq, diff\n            from public.exercises\n            where lower(name) = lower(ex_name)\n            limit 1;\n            is_bw := coalesce(eq = '{}', false) or coalesce('Bodyweight' = any(eq), false) or coalesce('Bodyweight/Weighted' = any(eq), false) or eq is null;\n            is_skill := diff in ('Advanced','Elite','Hard');\n            if is_bw and not is_skill then\n              target_reps := greatest(coalesce((ex->>'target_reps')::int,10),10);\n              target_sets := least(coalesce((ex->>'target_sets')::int, coalesce(jsonb_array_length(ex->'sets'),3)),4);\n              rest_ex := least(coalesce((ex->>'rest_time_sec')::int,60),90);\n              if ex ? 'sets' then\n                new_sets := (\n                  select coalesce(jsonb_agg(\n                    jsonb_set(\n                      jsonb_set(s, '{reps}', to_jsonb(greatest(coalesce((s->>'reps')::int, target_reps),10)), true),\n                      '{rest_time_sec}', to_jsonb(least(coalesce((s->>'rest_time_sec')::int, rest_ex),90)), true)\n                  ), '[]'::jsonb)\n                  from jsonb_array_elements(ex->'sets') with ordinality as t(s, ord)\n                  where ord <= 4\n                );\n              else\n                new_sets := ex->'sets';\n              end if;\n              ex := jsonb_set(ex, '{target_reps}', to_jsonb(target_reps), true);\n              ex := jsonb_set(ex, '{target_sets}', to_jsonb(target_sets), true);\n              ex := jsonb_set(ex, '{rest_time_sec}', to_jsonb(rest_ex), true);\n              if new_sets is not null then\n                ex := jsonb_set(ex, '{sets}', new_sets, true);\n              end if;\n            end if;\n            ex_array := ex_array || jsonb_build_array(ex);\n          end loop;\n          day_val := jsonb_set(day_val, '{exercises}', ex_array, true);\n        end if;\n        new_ws := new_ws || jsonb_build_object(day_key, day_val);\n      end loop;\n      wk_val := jsonb_set(wk_val, '{week_schedule}', new_ws, true);\n      new_weeks := new_weeks || jsonb_build_object(wk_key, wk_val);\n    end loop;\n    out_pd := jsonb_set(out_pd, '{weeks}', new_weeks, true);\n  end if;\n\n  return out_pd;\nend;\n$$;\n\n-- apply to all workout_plans\nupdate public.workout_plans\nset plan_data = public.adjust_bw_exercises(plan_data);\n"}	replace_adjust_bw_exercises_function	alexander.preo@gmail.com	\N	\N
20251210090617	{"create or replace function public.adjust_plan_data(pd jsonb)\nreturns jsonb\nlanguage plpgsql\nas $$\ndeclare\n  out_pd jsonb := coalesce(pd, '{}'::jsonb);\n  new_ws jsonb;\n  new_weeks jsonb := '{}'::jsonb;\n  day_key text;\n  day_val jsonb;\n  wk_key text;\n  wk_val jsonb;\n  ex jsonb;\n  ex_array jsonb;\n  eq text[];\n  diff text;\n  ex_is_timed bool;\n  is_bw bool;\n  is_skill bool;\n  handstand bool;\n  reordered jsonb;\n  tmp_arr jsonb;\n  new_sets jsonb;\nbegin\n  -- process top-level week_schedule\n  if out_pd ? 'week_schedule' then\n    new_ws := '{}'::jsonb;\n    for day_key, day_val in select key, value from jsonb_each(out_pd->'week_schedule') loop\n      if day_val is null then\n        new_ws := new_ws || jsonb_build_object(day_key, day_val);\n        continue;\n      end if;\n      if day_val ? 'exercises' then\n        reordered := '[]'::jsonb;\n        tmp_arr := '[]'::jsonb;\n        for ex in select value from jsonb_array_elements(day_val->'exercises') loop\n          select equipment_needed, difficulty_level, is_timed\n          into eq, diff, ex_is_timed\n          from public.exercises\n          where lower(name) = lower(ex->>'name')\n          limit 1;\n          is_bw := coalesce(eq = '{}', false) or coalesce('Bodyweight' = any(eq), false) or coalesce('Bodyweight/Weighted' = any(eq), false) or eq is null;\n          is_skill := diff in ('Hard','Elite');\n          handstand := lower(coalesce(ex->>'name','')) like '%handstand%';\n\n          -- Fatigue fix for BW Easy high-set or specific name\n          if (lower(coalesce(ex->>'name','')) = lower('Reverse Body Weight Lunge'))\n             or (is_bw and diff = 'Easy' and (ex ? 'sets' and jsonb_array_length(ex->'sets') > 4)) then\n            new_sets := jsonb_build_array(\n              jsonb_build_object('index',1,'reps',12,'rest_time_sec',90),\n              jsonb_build_object('index',2,'reps',12,'rest_time_sec',90),\n              jsonb_build_object('index',3,'reps',12,'rest_time_sec',90)\n            );\n            ex := jsonb_set(ex, '{target_sets}', to_jsonb(3), true);\n            ex := jsonb_set(ex, '{target_reps}', to_jsonb(12), true);\n            ex := jsonb_set(ex, '{rest_time_sec}', to_jsonb(90), true);\n            ex := jsonb_set(ex, '{sets}', new_sets, true);\n          end if;\n\n          -- Handstand UI: ensure reps present for timed\n          if handstand and (ex_is_timed or not (ex ? 'target_reps')) then\n            ex := jsonb_set(ex, '{target_reps}', to_jsonb(1), true);\n            if ex ? 'sets' then\n              new_sets := (\n                select coalesce(jsonb_agg(\n                  jsonb_set(s, '{reps}', to_jsonb(coalesce((s->>'reps')::int,1)), true)\n                ), '[]'::jsonb)\n                from jsonb_array_elements(ex->'sets') as t(s)\n              );\n              ex := jsonb_set(ex, '{sets}', new_sets, true);\n            end if;\n          end if;\n\n          if handstand or is_skill then\n            reordered := reordered || jsonb_build_array(ex);\n          else\n            tmp_arr := tmp_arr || jsonb_build_array(ex);\n          end if;\n        end loop;\n        ex_array := reordered || tmp_arr;\n        day_val := jsonb_set(day_val, '{exercises}', ex_array, true);\n      end if;\n      new_ws := new_ws || jsonb_build_object(day_key, day_val);\n    end loop;\n    out_pd := jsonb_set(out_pd, '{week_schedule}', new_ws, true);\n  end if;\n\n  -- process nested weeks\n  if out_pd ? 'weeks' then\n    new_weeks := '{}'::jsonb;\n    for wk_key, wk_val in select key, value from jsonb_each(out_pd->'weeks') loop\n      if wk_val is null or not (wk_val ? 'week_schedule') then\n        new_weeks := new_weeks || jsonb_build_object(wk_key, wk_val);\n        continue;\n      end if;\n      new_ws := '{}'::jsonb;\n      for day_key, day_val in select key, value from jsonb_each(wk_val->'week_schedule') loop\n        if day_val is null then\n          new_ws := new_ws || jsonb_build_object(day_key, day_val);\n          continue;\n        end if;\n        if day_val ? 'exercises' then\n          reordered := '[]'::jsonb;\n          tmp_arr := '[]'::jsonb;\n          for ex in select value from jsonb_array_elements(day_val->'exercises') loop\n            select equipment_needed, difficulty_level, is_timed\n            into eq, diff, ex_is_timed\n            from public.exercises\n            where lower(name) = lower(ex->>'name')\n            limit 1;\n            is_bw := coalesce(eq = '{}', false) or coalesce('Bodyweight' = any(eq), false) or coalesce('Bodyweight/Weighted' = any(eq), false) or eq is null;\n            is_skill := diff in ('Hard','Elite');\n            handstand := lower(coalesce(ex->>'name','')) like '%handstand%';\n\n            if (lower(coalesce(ex->>'name','')) = lower('Reverse Body Weight Lunge'))\n               or (is_bw and diff = 'Easy' and (ex ? 'sets' and jsonb_array_length(ex->'sets') > 4)) then\n              new_sets := jsonb_build_array(\n                jsonb_build_object('index',1,'reps',12,'rest_time_sec',90),\n                jsonb_build_object('index',2,'reps',12,'rest_time_sec',90),\n                jsonb_build_object('index',3,'reps',12,'rest_time_sec',90)\n              );\n              ex := jsonb_set(ex, '{target_sets}', to_jsonb(3), true);\n              ex := jsonb_set(ex, '{target_reps}', to_jsonb(12), true);\n              ex := jsonb_set(ex, '{rest_time_sec}', to_jsonb(90), true);\n              ex := jsonb_set(ex, '{sets}', new_sets, true);\n            end if;\n\n            if handstand and (ex_is_timed or not (ex ? 'target_reps')) then\n              ex := jsonb_set(ex, '{target_reps}', to_jsonb(1), true);\n              if ex ? 'sets' then\n                new_sets := (\n                  select coalesce(jsonb_agg(\n                    jsonb_set(s, '{reps}', to_jsonb(coalesce((s->>'reps')::int,1)), true)\n                  ), '[]'::jsonb)\n                  from jsonb_array_elements(ex->'sets') as t(s)\n                );\n                ex := jsonb_set(ex, '{sets}', new_sets, true);\n              end if;\n            end if;\n\n            if handstand or is_skill then\n              reordered := reordered || jsonb_build_array(ex);\n            else\n              tmp_arr := tmp_arr || jsonb_build_array(ex);\n            end if;\n          end loop;\n          ex_array := reordered || tmp_arr;\n          day_val := jsonb_set(day_val, '{exercises}', ex_array, true);\n        end if;\n        new_ws := new_ws || jsonb_build_object(day_key, day_val);\n      end loop;\n      wk_val := jsonb_set(wk_val, '{week_schedule}', new_ws, true);\n      new_weeks := new_weeks || jsonb_build_object(wk_key, wk_val);\n    end loop;\n    out_pd := jsonb_set(out_pd, '{weeks}', new_weeks, true);\n  end if;\n\n  return out_pd;\nend;\n$$;\n\nupdate public.workout_plans\nset plan_data = public.adjust_plan_data(plan_data);\n"}	fix_adjust_plan_data_function	alexander.preo@gmail.com	\N	\N
20251210091216	{"create or replace function public.adjust_plan_data(pd jsonb)\nreturns jsonb\nlanguage plpgsql\nas $$\ndeclare\n  out_pd jsonb := coalesce(pd, '{}'::jsonb);\n  new_ws jsonb;\n  new_weeks jsonb := '{}'::jsonb;\n  day_key text;\n  day_val jsonb;\n  wk_key text;\n  wk_val jsonb;\n  ex jsonb;\n  ex_array jsonb;\n  eq text[];\n  diff text;\n  ex_is_timed bool;\n  is_bw bool;\n  is_skill bool;\n  handstand bool;\n  reordered jsonb;\n  tmp_arr jsonb;\n  new_sets jsonb;\n  default_duration int := 60;\nbegin\n  -- process top-level week_schedule\n  if out_pd ? 'week_schedule' then\n    new_ws := '{}'::jsonb;\n    for day_key, day_val in select key, value from jsonb_each(out_pd->'week_schedule') loop\n      if day_val is null then\n        new_ws := new_ws || jsonb_build_object(day_key, day_val);\n        continue;\n      end if;\n      if day_val ? 'exercises' then\n        reordered := '[]'::jsonb;\n        tmp_arr := '[]'::jsonb;\n        for ex in select value from jsonb_array_elements(day_val->'exercises') loop\n          select equipment_needed, difficulty_level, is_timed\n          into eq, diff, ex_is_timed\n          from public.exercises\n          where lower(name) = lower(ex->>'name')\n          limit 1;\n          is_bw := coalesce(eq = '{}', false) or coalesce('Bodyweight' = any(eq), false) or coalesce('Bodyweight/Weighted' = any(eq), false) or eq is null;\n          is_skill := diff in ('Hard','Elite');\n          handstand := lower(coalesce(ex->>'name','')) like '%handstand%';\n\n          -- Fatigue fix for BW Easy high-set or specific name\n          if (lower(coalesce(ex->>'name','')) = lower('Reverse Body Weight Lunge'))\n             or (is_bw and diff = 'Easy' and (ex ? 'sets' and jsonb_array_length(ex->'sets') > 4)) then\n            new_sets := jsonb_build_array(\n              jsonb_build_object('index',1,'reps',12,'rest_time_sec',90),\n              jsonb_build_object('index',2,'reps',12,'rest_time_sec',90),\n              jsonb_build_object('index',3,'reps',12,'rest_time_sec',90)\n            );\n            ex := jsonb_set(ex, '{target_sets}', to_jsonb(3), true);\n            ex := jsonb_set(ex, '{target_reps}', to_jsonb(12), true);\n            ex := jsonb_set(ex, '{rest_time_sec}', to_jsonb(90), true);\n            ex := jsonb_set(ex, '{sets}', new_sets, true);\n          end if;\n\n          -- Handstand UI: ensure reps present for timed\n          if handstand and (ex_is_timed or not (ex ? 'target_reps')) then\n            ex := jsonb_set(ex, '{target_reps}', to_jsonb(1), true);\n            if ex ? 'sets' then\n              new_sets := (\n                select coalesce(jsonb_agg(\n                  jsonb_set(s, '{reps}', to_jsonb(coalesce((s->>'reps')::int,1)), true)\n                ), '[]'::jsonb)\n                from jsonb_array_elements(ex->'sets') as t(s)\n              );\n              ex := jsonb_set(ex, '{sets}', new_sets, true);\n            end if;\n          end if;\n\n          -- Timed display: ensure durations exist\n          if ex_is_timed or ex ? 'target_duration_sec' then\n            if not (ex ? 'target_duration_sec') or ex->>'target_duration_sec' is null then\n              ex := jsonb_set(ex, '{target_duration_sec}', to_jsonb(default_duration), true);\n            end if;\n            if ex ? 'sets' then\n              new_sets := (\n                select coalesce(jsonb_agg(\n                  jsonb_set(s, '{duration}', to_jsonb(coalesce((s->>'duration')::int, default_duration)), true)\n                ), '[]'::jsonb)\n                from jsonb_array_elements(ex->'sets') as t(s)\n              );\n              ex := jsonb_set(ex, '{sets}', new_sets, true);\n            end if;\n          end if;\n\n          if handstand or is_skill then\n            reordered := reordered || jsonb_build_array(ex);\n          else\n            tmp_arr := tmp_arr || jsonb_build_array(ex);\n          end if;\n        end loop;\n        ex_array := reordered || tmp_arr;\n        day_val := jsonb_set(day_val, '{exercises}', ex_array, true);\n      end if;\n      new_ws := new_ws || jsonb_build_object(day_key, day_val);\n    end loop;\n    out_pd := jsonb_set(out_pd, '{week_schedule}', new_ws, true);\n  end if;\n\n  -- process nested weeks\n  if out_pd ? 'weeks' then\n    new_weeks := '{}'::jsonb;\n    for wk_key, wk_val in select key, value from jsonb_each(out_pd->'weeks') loop\n      if wk_val is null or not (wk_val ? 'week_schedule') then\n        new_weeks := new_weeks || jsonb_build_object(wk_key, wk_val);\n        continue;\n      end if;\n      new_ws := '{}'::jsonb;\n      for day_key, day_val in select key, value from jsonb_each(wk_val->'week_schedule') loop\n        if day_val is null then\n          new_ws := new_ws || jsonb_build_object(day_key, day_val);\n          continue;\n        end if;\n        if day_val ? 'exercises' then\n          reordered := '[]'::jsonb;\n          tmp_arr := '[]'::jsonb;\n          for ex in select value from jsonb_array_elements(day_val->'exercises') loop\n            select equipment_needed, difficulty_level, is_timed\n            into eq, diff, ex_is_timed\n            from public.exercises\n            where lower(name) = lower(ex->>'name')\n            limit 1;\n            is_bw := coalesce(eq = '{}', false) or coalesce('Bodyweight' = any(eq), false) or coalesce('Bodyweight/Weighted' = any(eq), false) or eq is null;\n            is_skill := diff in ('Hard','Elite');\n            handstand := lower(coalesce(ex->>'name','')) like '%handstand%';\n\n            if (lower(coalesce(ex->>'name','')) = lower('Reverse Body Weight Lunge'))\n               or (is_bw and diff = 'Easy' and (ex ? 'sets' and jsonb_array_length(ex->'sets') > 4)) then\n              new_sets := jsonb_build_array(\n                jsonb_build_object('index',1,'reps',12,'rest_time_sec',90),\n                jsonb_build_object('index',2,'reps',12,'rest_time_sec',90),\n                jsonb_build_object('index',3,'reps',12,'rest_time_sec',90)\n              );\n              ex := jsonb_set(ex, '{target_sets}', to_jsonb(3), true);\n              ex := jsonb_set(ex, '{target_reps}', to_jsonb(12), true);\n              ex := jsonb_set(ex, '{rest_time_sec}', to_jsonb(90), true);\n              ex := jsonb_set(ex, '{sets}', new_sets, true);\n            end if;\n\n            if handstand and (ex_is_timed or not (ex ? 'target_reps')) then\n              ex := jsonb_set(ex, '{target_reps}', to_jsonb(1), true);\n              if ex ? 'sets' then\n                new_sets := (\n                  select coalesce(jsonb_agg(\n                    jsonb_set(s, '{reps}', to_jsonb(coalesce((s->>'reps')::int,1)), true)\n                  ), '[]'::jsonb)\n                  from jsonb_array_elements(ex->'sets') as t(s)\n                );\n                ex := jsonb_set(ex, '{sets}', new_sets, true);\n              end if;\n            end if;\n\n            if ex_is_timed or ex ? 'target_duration_sec' then\n              if not (ex ? 'target_duration_sec') or ex->>'target_duration_sec' is null then\n                ex := jsonb_set(ex, '{target_duration_sec}', to_jsonb(default_duration), true);\n              end if;\n              if ex ? 'sets' then\n                new_sets := (\n                  select coalesce(jsonb_agg(\n                    jsonb_set(s, '{duration}', to_jsonb(coalesce((s->>'duration')::int, default_duration)), true)\n                  ), '[]'::jsonb)\n                  from jsonb_array_elements(ex->'sets') as t(s)\n                );\n                ex := jsonb_set(ex, '{sets}', new_sets, true);\n              end if;\n            end if;\n\n            if handstand or is_skill then\n              reordered := reordered || jsonb_build_array(ex);\n            else\n              tmp_arr := tmp_arr || jsonb_build_array(ex);\n            end if;\n          end loop;\n          ex_array := reordered || tmp_arr;\n          day_val := jsonb_set(day_val, '{exercises}', ex_array, true);\n        end if;\n        new_ws := new_ws || jsonb_build_object(day_key, day_val);\n      end loop;\n      wk_val := jsonb_set(wk_val, '{week_schedule}', new_ws, true);\n      new_weeks := new_weeks || jsonb_build_object(wk_key, wk_val);\n    end loop;\n    out_pd := jsonb_set(out_pd, '{weeks}', new_weeks, true);\n  end if;\n\n  return out_pd;\nend;\n$$;\n\nupdate public.workout_plans\nset plan_data = public.adjust_plan_data(plan_data);\n"}	update_adjust_plan_data_add_duration_defaults	alexander.preo@gmail.com	\N	\N
20251214200437	{"-- IronPath V2: Create all v2_* tables\n-- This migration creates the complete V2 schema as specified in V2_ARCHITECTURE.md\n\n-- ============================================================================\n-- 1. Canonical muscles (reference data)\n-- ============================================================================\nCREATE TABLE IF NOT EXISTS v2_muscles (\n  key text PRIMARY KEY,\n  display_name text NOT NULL,\n  \\"group\\" text,\n  sort_order int,\n  is_active boolean DEFAULT true,\n  created_at timestamptz DEFAULT now(),\n  updated_at timestamptz DEFAULT now()\n);\n\nCOMMENT ON TABLE v2_muscles IS 'Canonical muscle keys used for validation across all exercise metadata';\n\n-- ============================================================================\n-- 2. Exercise master list (immutable from client)\n-- ============================================================================\nCREATE TABLE IF NOT EXISTS v2_exercises (\n  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),\n  name text NOT NULL,\n  description text,\n  density_score numeric NOT NULL,\n  primary_muscles text[] NOT NULL,\n  secondary_muscles text[],\n  implicit_hits jsonb NOT NULL,\n  is_unilateral boolean NOT NULL,\n  setup_buffer_sec int NOT NULL,\n  avg_time_per_set_sec int NOT NULL,\n  is_timed boolean NOT NULL DEFAULT false,\n  equipment_needed text[],\n  movement_pattern text,\n  tempo_category text,\n  created_at timestamptz DEFAULT now(),\n  updated_at timestamptz DEFAULT now(),\n  CONSTRAINT density_score_check CHECK (density_score >= 0 AND density_score <= 10)\n);\n\nCOMMENT ON TABLE v2_exercises IS 'Master exercise list - immutable from client, only admin/service can write';\nCOMMENT ON COLUMN v2_exercises.avg_time_per_set_sec IS 'Includes rest time between sets';\nCOMMENT ON COLUMN v2_exercises.implicit_hits IS 'JSONB map: muscle_key -> activation (0..1)';\n\n-- ============================================================================\n-- 3. Exercise prescriptions (curated targets)\n-- ============================================================================\nCREATE TABLE IF NOT EXISTS v2_exercise_prescriptions (\n  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),\n  exercise_id uuid NOT NULL REFERENCES v2_exercises(id) ON DELETE CASCADE,\n  goal text NOT NULL,\n  experience text NOT NULL,\n  mode text NOT NULL CHECK (mode IN ('reps', 'timed')),\n  sets_min int NOT NULL,\n  sets_max int NOT NULL,\n  reps_min int,\n  reps_max int,\n  duration_sec_min int,\n  duration_sec_max int,\n  is_active boolean NOT NULL DEFAULT true,\n  source_notes text,\n  created_at timestamptz DEFAULT now(),\n  updated_at timestamptz DEFAULT now(),\n  UNIQUE (exercise_id, goal, experience, mode),\n  CONSTRAINT sets_check CHECK (sets_min >= 1 AND sets_max >= sets_min AND sets_max <= 10),\n  CONSTRAINT reps_bounds_check CHECK (\n    (mode = 'reps' AND reps_min IS NOT NULL AND reps_max IS NOT NULL AND reps_min >= 1 AND reps_max >= reps_min AND reps_max <= 50 AND duration_sec_min IS NULL AND duration_sec_max IS NULL) OR\n    (mode = 'timed' AND duration_sec_min IS NOT NULL AND duration_sec_max IS NOT NULL AND duration_sec_min >= 5 AND duration_sec_max >= duration_sec_min AND duration_sec_max <= 3600 AND reps_min IS NULL AND reps_max IS NULL)\n  )\n);\n\nCOMMENT ON TABLE v2_exercise_prescriptions IS 'Curated programming targets per exercise by context (goal, experience, mode)';\n\n-- ============================================================================\n-- 4. AI recommended exercises (allow-list)\n-- ============================================================================\nCREATE TABLE IF NOT EXISTS v2_ai_recommended_exercises (\n  exercise_id uuid PRIMARY KEY REFERENCES v2_exercises(id) ON DELETE CASCADE,\n  is_active boolean NOT NULL DEFAULT true,\n  priority_order int,\n  notes text,\n  created_at timestamptz DEFAULT now(),\n  updated_at timestamptz DEFAULT now()\n);\n\nCOMMENT ON TABLE v2_ai_recommended_exercises IS 'AI allow-list: only exercises in this table can be selected by AI generation';\n\n-- ============================================================================\n-- 5. User exercise overrides\n-- ============================================================================\nCREATE TABLE IF NOT EXISTS v2_user_exercise_overrides (\n  user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,\n  exercise_id uuid NOT NULL REFERENCES v2_exercises(id) ON DELETE CASCADE,\n  density_score_override numeric,\n  primary_muscles_override text[],\n  implicit_hits_override jsonb,\n  is_unilateral_override boolean,\n  setup_buffer_sec_override int,\n  avg_time_per_set_sec_override int,\n  is_timed_override boolean,\n  created_at timestamptz DEFAULT now(),\n  updated_at timestamptz DEFAULT now(),\n  PRIMARY KEY (user_id, exercise_id),\n  CONSTRAINT density_score_override_check CHECK (density_score_override IS NULL OR (density_score_override >= 0 AND density_score_override <= 10))\n);\n\nCOMMENT ON TABLE v2_user_exercise_overrides IS 'User-specific overrides for master exercises. Non-null overrides take precedence over global defaults.';\n\n-- ============================================================================\n-- 6. User custom exercises\n-- ============================================================================\nCREATE TABLE IF NOT EXISTS v2_user_custom_exercises (\n  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),\n  user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,\n  name text NOT NULL,\n  description text,\n  density_score numeric NOT NULL,\n  primary_muscles text[] NOT NULL,\n  secondary_muscles text[],\n  implicit_hits jsonb NOT NULL,\n  is_unilateral boolean NOT NULL,\n  setup_buffer_sec int NOT NULL,\n  avg_time_per_set_sec int NOT NULL,\n  is_timed boolean NOT NULL DEFAULT false,\n  equipment_needed text[],\n  movement_pattern text,\n  tempo_category text,\n  created_at timestamptz DEFAULT now(),\n  updated_at timestamptz DEFAULT now(),\n  CONSTRAINT density_score_check CHECK (density_score >= 0 AND density_score <= 10)\n);\n\nCOMMENT ON TABLE v2_user_custom_exercises IS 'User-created exercises not in master list. Must include required metadata for engine eligibility.';\n\n-- ============================================================================\n-- 7. Profiles (user settings)\n-- ============================================================================\nCREATE TABLE IF NOT EXISTS v2_profiles (\n  id uuid PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE,\n  full_name text,\n  age int,\n  gender text,\n  height numeric,\n  current_weight numeric,\n  goal_weight numeric,\n  experience_level text,\n  goal text,\n  equipment_access text[],\n  days_per_week int,\n  workout_days text[],\n  preferred_training_style text,\n  use_imperial boolean DEFAULT true,\n  avatar_url text,\n  created_at timestamptz DEFAULT now(),\n  updated_at timestamptz DEFAULT now()\n);\n\nCOMMENT ON TABLE v2_profiles IS 'User profile and preferences';\n\n-- ============================================================================\n-- 8. Workout templates (planning)\n-- ============================================================================\nCREATE TABLE IF NOT EXISTS v2_workout_templates (\n  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),\n  user_id uuid REFERENCES auth.users(id) ON DELETE CASCADE,\n  name text NOT NULL DEFAULT 'Weekly Plan',\n  is_active boolean DEFAULT true,\n  created_at timestamptz DEFAULT now(),\n  updated_at timestamptz DEFAULT now()\n);\n\nCREATE TABLE IF NOT EXISTS v2_template_days (\n  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),\n  template_id uuid NOT NULL REFERENCES v2_workout_templates(id) ON DELETE CASCADE,\n  day_name text NOT NULL,\n  sort_order int NOT NULL,\n  created_at timestamptz DEFAULT now(),\n  updated_at timestamptz DEFAULT now(),\n  UNIQUE (template_id, day_name)\n);\n\nCREATE TABLE IF NOT EXISTS v2_template_slots (\n  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),\n  day_id uuid NOT NULL REFERENCES v2_template_days(id) ON DELETE CASCADE,\n  exercise_id uuid REFERENCES v2_exercises(id) ON DELETE SET NULL,\n  goal text,\n  experience text,\n  notes text,\n  sort_order int NOT NULL,\n  created_at timestamptz DEFAULT now(),\n  updated_at timestamptz DEFAULT now()\n);\n\nCOMMENT ON TABLE v2_workout_templates IS 'Workout plan templates - structure and intent only';\nCOMMENT ON TABLE v2_template_days IS 'Days within a template';\nCOMMENT ON TABLE v2_template_slots IS 'Exercise slots within a day. Targets come from prescriptions, not hardcoded here.';\n\n-- ============================================================================\n-- 9. Performed truth (sessions and sets)\n-- ============================================================================\nCREATE TABLE IF NOT EXISTS v2_workout_sessions (\n  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),\n  user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,\n  template_id uuid REFERENCES v2_workout_templates(id) ON DELETE SET NULL,\n  day_name text,\n  status text NOT NULL DEFAULT 'active' CHECK (status IN ('active', 'completed', 'abandoned')),\n  started_at timestamptz DEFAULT now(),\n  completed_at timestamptz\n);\n\nCREATE TABLE IF NOT EXISTS v2_session_exercises (\n  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),\n  session_id uuid NOT NULL REFERENCES v2_workout_sessions(id) ON DELETE CASCADE,\n  exercise_id uuid REFERENCES v2_exercises(id) ON DELETE SET NULL,\n  custom_exercise_id uuid REFERENCES v2_user_custom_exercises(id) ON DELETE SET NULL,\n  sort_order int NOT NULL,\n  created_at timestamptz DEFAULT now(),\n  CONSTRAINT exercise_reference_check CHECK (\n    (exercise_id IS NOT NULL AND custom_exercise_id IS NULL) OR\n    (exercise_id IS NULL AND custom_exercise_id IS NOT NULL)\n  )\n);\n\nCREATE TABLE IF NOT EXISTS v2_session_sets (\n  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),\n  session_exercise_id uuid NOT NULL REFERENCES v2_session_exercises(id) ON DELETE CASCADE,\n  set_number int NOT NULL,\n  reps int,\n  weight numeric,\n  rpe int,\n  rir int,\n  duration_sec int,\n  rest_sec int,\n  notes text,\n  performed_at timestamptz DEFAULT now(),\n  CONSTRAINT reps_check CHECK (reps IS NULL OR reps BETWEEN 1 AND 50),\n  CONSTRAINT weight_check CHECK (weight IS NULL OR weight >= 0),\n  CONSTRAINT rpe_check CHECK (rpe IS NULL OR rpe BETWEEN 1 AND 10),\n  CONSTRAINT duration_sec_check CHECK (duration_sec IS NULL OR duration_sec BETWEEN 5 AND 3600),\n  CONSTRAINT rest_sec_check CHECK (rest_sec IS NULL OR rest_sec BETWEEN 0 AND 600),\n  CONSTRAINT mode_exclusivity_check CHECK (NOT (reps IS NOT NULL AND duration_sec IS NOT NULL)),\n  CONSTRAINT mode_required_check CHECK (reps IS NOT NULL OR duration_sec IS NOT NULL),\n  CONSTRAINT rpe_rir_exclusivity_check CHECK (NOT (rpe IS NOT NULL AND rir IS NOT NULL))\n);\n\nCOMMENT ON TABLE v2_workout_sessions IS 'Performed workout sessions - the truth source for what actually happened';\nCOMMENT ON TABLE v2_session_exercises IS 'Exercises performed in a session';\nCOMMENT ON TABLE v2_session_sets IS 'Individual sets performed. Must have either reps or duration_sec, not both.';\n\n-- ============================================================================\n-- 10. Optional derived caches (rebuildable)\n-- ============================================================================\nCREATE TABLE IF NOT EXISTS v2_muscle_freshness (\n  user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,\n  muscle_key text NOT NULL REFERENCES v2_muscles(key) ON DELETE CASCADE,\n  freshness numeric NOT NULL DEFAULT 100 CHECK (freshness >= 0 AND freshness <= 100),\n  last_trained_at timestamptz,\n  updated_at timestamptz DEFAULT now(),\n  PRIMARY KEY (user_id, muscle_key)\n);\n\nCREATE TABLE IF NOT EXISTS v2_daily_muscle_stress (\n  user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,\n  date date NOT NULL,\n  muscle_key text NOT NULL REFERENCES v2_muscles(key) ON DELETE CASCADE,\n  stress numeric NOT NULL DEFAULT 0,\n  updated_at timestamptz DEFAULT now(),\n  PRIMARY KEY (user_id, date, muscle_key)\n);\n\nCOMMENT ON TABLE v2_muscle_freshness IS 'Derived cache: muscle recovery state (0-100). Rebuildable from v2_session_sets.';\nCOMMENT ON TABLE v2_daily_muscle_stress IS 'Derived cache: daily muscle stress aggregation. Used for heatmap. Rebuildable from v2_session_sets.';\n\n-- ============================================================================\n-- Indexes for performance\n-- ============================================================================\nCREATE INDEX IF NOT EXISTS idx_v2_exercises_density_score ON v2_exercises(density_score);\nCREATE INDEX IF NOT EXISTS idx_v2_exercise_prescriptions_lookup ON v2_exercise_prescriptions(exercise_id, goal, experience, mode, is_active);\nCREATE INDEX IF NOT EXISTS idx_v2_ai_recommended_exercises_active ON v2_ai_recommended_exercises(is_active, priority_order);\nCREATE INDEX IF NOT EXISTS idx_v2_user_exercise_overrides_user ON v2_user_exercise_overrides(user_id);\nCREATE INDEX IF NOT EXISTS idx_v2_user_custom_exercises_user ON v2_user_custom_exercises(user_id);\nCREATE INDEX IF NOT EXISTS idx_v2_workout_sessions_user ON v2_workout_sessions(user_id, started_at);\nCREATE INDEX IF NOT EXISTS idx_v2_session_exercises_session ON v2_session_exercises(session_id, sort_order);\nCREATE INDEX IF NOT EXISTS idx_v2_session_sets_exercise ON v2_session_sets(session_exercise_id, set_number);\nCREATE INDEX IF NOT EXISTS idx_v2_muscle_freshness_user ON v2_muscle_freshness(user_id);\nCREATE INDEX IF NOT EXISTS idx_v2_daily_muscle_stress_user_date ON v2_daily_muscle_stress(user_id, date);"}	create_v2_tables	alexander.preo@gmail.com	\N	\N
20251214200502	{"-- IronPath V2: RLS Policies\n-- Implements table-by-table RLS as specified in V2_ARCHITECTURE.md\n\n-- ============================================================================\n-- Enable RLS on all tables\n-- ============================================================================\nALTER TABLE v2_muscles ENABLE ROW LEVEL SECURITY;\nALTER TABLE v2_exercises ENABLE ROW LEVEL SECURITY;\nALTER TABLE v2_exercise_prescriptions ENABLE ROW LEVEL SECURITY;\nALTER TABLE v2_ai_recommended_exercises ENABLE ROW LEVEL SECURITY;\nALTER TABLE v2_user_exercise_overrides ENABLE ROW LEVEL SECURITY;\nALTER TABLE v2_user_custom_exercises ENABLE ROW LEVEL SECURITY;\nALTER TABLE v2_profiles ENABLE ROW LEVEL SECURITY;\nALTER TABLE v2_workout_templates ENABLE ROW LEVEL SECURITY;\nALTER TABLE v2_template_days ENABLE ROW LEVEL SECURITY;\nALTER TABLE v2_template_slots ENABLE ROW LEVEL SECURITY;\nALTER TABLE v2_workout_sessions ENABLE ROW LEVEL SECURITY;\nALTER TABLE v2_session_exercises ENABLE ROW LEVEL SECURITY;\nALTER TABLE v2_session_sets ENABLE ROW LEVEL SECURITY;\nALTER TABLE v2_muscle_freshness ENABLE ROW LEVEL SECURITY;\nALTER TABLE v2_daily_muscle_stress ENABLE ROW LEVEL SECURITY;\n\n-- ============================================================================\n-- Immutable tables: auth SELECT only, no writes from client\n-- ============================================================================\n\n-- v2_muscles: auth SELECT only\nCREATE POLICY \\"v2_muscles_select_auth\\" ON v2_muscles\n  FOR SELECT\n  TO authenticated\n  USING (true);\n\n-- v2_exercises: auth SELECT only (immutable from client)\nCREATE POLICY \\"v2_exercises_select_auth\\" ON v2_exercises\n  FOR SELECT\n  TO authenticated\n  USING (true);\n\n-- v2_exercise_prescriptions: auth SELECT only\nCREATE POLICY \\"v2_exercise_prescriptions_select_auth\\" ON v2_exercise_prescriptions\n  FOR SELECT\n  TO authenticated\n  USING (true);\n\n-- v2_ai_recommended_exercises: auth SELECT only\nCREATE POLICY \\"v2_ai_recommended_exercises_select_auth\\" ON v2_ai_recommended_exercises\n  FOR SELECT\n  TO authenticated\n  USING (true);\n\n-- ============================================================================\n-- User-owned tables: auth CRUD for owner only\n-- ============================================================================\n\n-- v2_user_exercise_overrides: owner CRUD\nCREATE POLICY \\"v2_user_exercise_overrides_owner\\" ON v2_user_exercise_overrides\n  FOR ALL\n  TO authenticated\n  USING (user_id = auth.uid())\n  WITH CHECK (user_id = auth.uid());\n\n-- v2_user_custom_exercises: owner CRUD\nCREATE POLICY \\"v2_user_custom_exercises_owner\\" ON v2_user_custom_exercises\n  FOR ALL\n  TO authenticated\n  USING (user_id = auth.uid())\n  WITH CHECK (user_id = auth.uid());\n\n-- v2_profiles: owner CRUD\nCREATE POLICY \\"v2_profiles_owner\\" ON v2_profiles\n  FOR ALL\n  TO authenticated\n  USING (id = auth.uid())\n  WITH CHECK (id = auth.uid());\n\n-- v2_workout_templates: owner CRUD\nCREATE POLICY \\"v2_workout_templates_owner\\" ON v2_workout_templates\n  FOR ALL\n  TO authenticated\n  USING (user_id = auth.uid() OR user_id IS NULL)\n  WITH CHECK (user_id = auth.uid() OR user_id IS NULL);\n\n-- v2_template_days: owner via template\nCREATE POLICY \\"v2_template_days_owner\\" ON v2_template_days\n  FOR ALL\n  TO authenticated\n  USING (\n    EXISTS (\n      SELECT 1 FROM v2_workout_templates\n      WHERE v2_workout_templates.id = v2_template_days.template_id\n      AND (v2_workout_templates.user_id = auth.uid() OR v2_workout_templates.user_id IS NULL)\n    )\n  )\n  WITH CHECK (\n    EXISTS (\n      SELECT 1 FROM v2_workout_templates\n      WHERE v2_workout_templates.id = v2_template_days.template_id\n      AND (v2_workout_templates.user_id = auth.uid() OR v2_workout_templates.user_id IS NULL)\n    )\n  );\n\n-- v2_template_slots: owner via template\nCREATE POLICY \\"v2_template_slots_owner\\" ON v2_template_slots\n  FOR ALL\n  TO authenticated\n  USING (\n    EXISTS (\n      SELECT 1 FROM v2_template_days\n      JOIN v2_workout_templates ON v2_workout_templates.id = v2_template_days.template_id\n      WHERE v2_template_days.id = v2_template_slots.day_id\n      AND (v2_workout_templates.user_id = auth.uid() OR v2_workout_templates.user_id IS NULL)\n    )\n  )\n  WITH CHECK (\n    EXISTS (\n      SELECT 1 FROM v2_template_days\n      JOIN v2_workout_templates ON v2_workout_templates.id = v2_template_days.template_id\n      WHERE v2_template_days.id = v2_template_slots.day_id\n      AND (v2_workout_templates.user_id = auth.uid() OR v2_workout_templates.user_id IS NULL)\n    )\n  );\n\n-- v2_workout_sessions: owner CRUD\nCREATE POLICY \\"v2_workout_sessions_owner\\" ON v2_workout_sessions\n  FOR ALL\n  TO authenticated\n  USING (user_id = auth.uid())\n  WITH CHECK (user_id = auth.uid());\n\n-- v2_session_exercises: owner via session\nCREATE POLICY \\"v2_session_exercises_owner\\" ON v2_session_exercises\n  FOR ALL\n  TO authenticated\n  USING (\n    EXISTS (\n      SELECT 1 FROM v2_workout_sessions\n      WHERE v2_workout_sessions.id = v2_session_exercises.session_id\n      AND v2_workout_sessions.user_id = auth.uid()\n    )\n  )\n  WITH CHECK (\n    EXISTS (\n      SELECT 1 FROM v2_workout_sessions\n      WHERE v2_workout_sessions.id = v2_session_exercises.session_id\n      AND v2_workout_sessions.user_id = auth.uid()\n    )\n  );\n\n-- v2_session_sets: owner via session\nCREATE POLICY \\"v2_session_sets_owner\\" ON v2_session_sets\n  FOR ALL\n  TO authenticated\n  USING (\n    EXISTS (\n      SELECT 1 FROM v2_session_exercises\n      JOIN v2_workout_sessions ON v2_workout_sessions.id = v2_session_exercises.session_id\n      WHERE v2_session_exercises.id = v2_session_sets.session_exercise_id\n      AND v2_workout_sessions.user_id = auth.uid()\n    )\n  )\n  WITH CHECK (\n    EXISTS (\n      SELECT 1 FROM v2_session_exercises\n      JOIN v2_workout_sessions ON v2_workout_sessions.id = v2_session_exercises.session_id\n      WHERE v2_session_exercises.id = v2_session_sets.session_exercise_id\n      AND v2_workout_sessions.user_id = auth.uid()\n    )\n  );\n\n-- v2_muscle_freshness: owner CRUD\nCREATE POLICY \\"v2_muscle_freshness_owner\\" ON v2_muscle_freshness\n  FOR ALL\n  TO authenticated\n  USING (user_id = auth.uid())\n  WITH CHECK (user_id = auth.uid());\n\n-- v2_daily_muscle_stress: owner CRUD\nCREATE POLICY \\"v2_daily_muscle_stress_owner\\" ON v2_daily_muscle_stress\n  FOR ALL\n  TO authenticated\n  USING (user_id = auth.uid())\n  WITH CHECK (user_id = auth.uid());"}	create_v2_rls_policies	alexander.preo@gmail.com	\N	\N
20251221135010	{"-- Patch: Seed v2_muscles with comprehensive muscle list\n-- Idempotent: can re-run safely using ON CONFLICT DO NOTHING\n-- Total: 28 muscles organized by functional groups\n\n-- Upper Body Push (group: upper_body_push)\nINSERT INTO v2_muscles (key, display_name, \\"group\\", sort_order, is_active) VALUES\n  ('chest', 'Chest', 'upper_body_push', 1, true),\n  ('upper_chest', 'Upper Chest', 'upper_body_push', 2, true),\n  ('lower_chest', 'Lower Chest', 'upper_body_push', 3, true),\n  ('anterior_deltoids', 'Front Delts', 'upper_body_push', 4, true),\n  ('lateral_deltoids', 'Side Delts', 'upper_body_push', 5, true),\n  ('posterior_deltoids', 'Rear Delts', 'upper_body_push', 6, true),\n  ('triceps', 'Triceps', 'upper_body_push', 7, true)\nON CONFLICT (key) DO NOTHING;\n\n-- Upper Body Pull (group: upper_body_pull)\nINSERT INTO v2_muscles (key, display_name, \\"group\\", sort_order, is_active) VALUES\n  ('lats', 'Lats', 'upper_body_pull', 1, true),\n  ('upper_back', 'Upper Back', 'upper_body_pull', 2, true),\n  ('lower_back', 'Lower Back', 'upper_body_pull', 3, true),\n  ('traps', 'Traps', 'upper_body_pull', 4, true),\n  ('biceps', 'Biceps', 'upper_body_pull', 5, true),\n  ('forearms', 'Forearms', 'upper_body_pull', 6, true)\nON CONFLICT (key) DO NOTHING;\n\n-- Core (group: core)\nINSERT INTO v2_muscles (key, display_name, \\"group\\", sort_order, is_active) VALUES\n  ('abs', 'Abs', 'core', 1, true),\n  ('obliques', 'Obliques', 'core', 2, true)\nON CONFLICT (key) DO NOTHING;\n\n-- Lower Body Front (group: lower_body_front)\nINSERT INTO v2_muscles (key, display_name, \\"group\\", sort_order, is_active) VALUES\n  ('quads', 'Quadriceps', 'lower_body_front', 1, true),\n  ('hip_flexors', 'Hip Flexors', 'lower_body_front', 2, true)\nON CONFLICT (key) DO NOTHING;\n\n-- Lower Body Back (group: lower_body_back)\nINSERT INTO v2_muscles (key, display_name, \\"group\\", sort_order, is_active) VALUES\n  ('hamstrings', 'Hamstrings', 'lower_body_back', 1, true),\n  ('glutes', 'Glutes', 'lower_body_back', 2, true),\n  ('calves', 'Calves', 'lower_body_back', 3, true),\n  ('soleus', 'Soleus', 'lower_body_back', 4, true)\nON CONFLICT (key) DO NOTHING;\n\n-- Stabilizers (group: stabilizers)\nINSERT INTO v2_muscles (key, display_name, \\"group\\", sort_order, is_active) VALUES\n  ('rotator_cuff', 'Rotator Cuff', 'stabilizers', 1, true),\n  ('serratus_anterior', 'Serratus Anterior', 'stabilizers', 2, true),\n  ('transverse_abdominis', 'Transverse Abdominis', 'stabilizers', 3, true),\n  ('glute_medius', 'Glute Medius', 'stabilizers', 4, true),\n  ('glute_minimus', 'Glute Minimus', 'stabilizers', 5, true),\n  ('piriformis', 'Piriformis', 'stabilizers', 6, true),\n  ('tibialis_anterior', 'Tibialis Anterior', 'stabilizers', 7, true)\nON CONFLICT (key) DO NOTHING;"}	seed_v2_muscles	alexander.preo@gmail.com	\N	\N
20260103004604	{"-- Patch: Split full_name into first_name and last_name in v2_profiles\n-- Migration: 20250101000005_split_full_name.sql\n\n-- Step 1: Add new columns\nALTER TABLE v2_profiles\n  ADD COLUMN IF NOT EXISTS first_name text,\n  ADD COLUMN IF NOT EXISTS last_name text;\n\n-- Step 2: Migrate existing data (split full_name into first_name and last_name)\n-- For existing records, try to split on space (take first word as first_name, rest as last_name)\nUPDATE v2_profiles\nSET\n  first_name = CASE\n    WHEN full_name IS NULL OR full_name = '' THEN NULL\n    WHEN position(' ' in full_name) > 0 THEN split_part(full_name, ' ', 1)\n    ELSE full_name\n  END,\n  last_name = CASE\n    WHEN full_name IS NULL OR full_name = '' THEN NULL\n    WHEN position(' ' in full_name) > 0 THEN substring(full_name from position(' ' in full_name) + 1)\n    ELSE NULL\n  END\nWHERE first_name IS NULL OR last_name IS NULL;\n\n-- Step 3: Drop the old full_name column\nALTER TABLE v2_profiles DROP COLUMN IF EXISTS full_name;\n\n-- Step 4: Add constraint to make first_name required (NOT NULL)\n-- Note: We allow NULL for now to handle existing data, but new inserts should require first_name\n-- The application layer will enforce first_name as required\n\nCOMMENT ON COLUMN v2_profiles.first_name IS 'User first name (required)';\nCOMMENT ON COLUMN v2_profiles.last_name IS 'User last name (optional)';"}	split_full_name	alexander.preo@gmail.com	\N	\N
20260103004821	{"-- Patch: Change age column to date_of_birth in v2_profiles\n-- Migration: 20250101000006_change_age_to_date_of_birth.sql\n\n-- Step 1: Add new date_of_birth column\nALTER TABLE v2_profiles\n  ADD COLUMN IF NOT EXISTS date_of_birth date;\n\n-- Step 2: Migrate existing age data to approximate date_of_birth\n-- Calculate approximate birth year from current age (assumes birthday has passed this year)\n-- This is an approximation - we use January 1st as a default day\nUPDATE v2_profiles\nSET date_of_birth = CASE\n  WHEN age IS NOT NULL THEN \n    (CURRENT_DATE - INTERVAL '1 year' * age)::date\n  ELSE NULL\nEND\nWHERE date_of_birth IS NULL AND age IS NOT NULL;\n\n-- Step 3: Drop the old age column\nALTER TABLE v2_profiles DROP COLUMN IF EXISTS age;\n\n-- Step 4: Add comment\nCOMMENT ON COLUMN v2_profiles.date_of_birth IS 'User date of birth (used to calculate age dynamically)';"}	change_age_to_date_of_birth	alexander.preo@gmail.com	\N	\N
